 let arenaAttachSerial=0;
 async function attachArena(state){
  const epoch=viewEpoch,attempt=++arenaAttachSerial,stage=arenaStage;
  const current=()=>epoch===viewEpoch&&attempt===arenaAttachSerial&&screen==='battle'&&arenaStage===stage;
  if(!arenaScene)setArenaLoading(true,state.units.length);stage.dataset.loadComplete='false';
  let scene,warningTimer,loadingTimer;
  try{
   if(!arenaLoading)arenaLoading=import('./creature-brawl-arena.js?v=kael-shadow4');
   const {BrawlArena}=await arenaLoading;if(!current())return;
   if(!arenaScene)arenaScene=new BrawlArena(stage,{onTarget:targetClick,onHover:showPrediction,onError:graphicsError});
   scene=arenaScene;scene.setQuality(lowGraphics);
   warningTimer=setTimeout(()=>{if(current()){const tip=room.querySelector('.cb-loading-tip');if(tip)tip.textContent='Large creatures can take longer on the first visit. Preparing models and animations...';}},15000);
   await Promise.race([scene.sync(state.units,state.actorId),new Promise((_,reject)=>{loadingTimer=setTimeout(()=>reject(Error('Model loading did not finish within 90 seconds. Check your connection, then retry graphics.')),90000);})]);
   if(!current()||scene!==arenaScene)return;
   scene.bindHUD();stage.dataset.loadComplete='true';stage.querySelectorAll('.cb-fallback-portrait,.cb-scene-notice').forEach(n=>n.remove());setArenaLoading(false);
   if(targeting)scene.setTargets(E.legal(state,targeting.moveId).targets);
  }catch(error){
   if(!current())return;
   if(scene&&scene===arenaScene){scene.dispose();arenaScene=null;}
   setArenaLoading(false);stage.dataset.loadComplete='true';graphicsError('The 3D arena could not start. '+error.message);
  }finally{clearTimeout(warningTimer);clearTimeout(loadingTimer);}
 }
